// Each row is the shape the dashboard saves (widgetSpec.ts), and the widgets
// service plans it against the analytics catalog and checks the chart against
// it, so the list reads them as valid. Rows cascade with the demo project,
// which the reset at the top deletes.
func (q *Queries) ActivityInsertWidgets(ctx context.Context, arg ActivityInsertWidgetsParams) error {
	_, err := q.db.Exec(ctx, activityInsertWidgets,
		arg.Widget1ID,
		arg.ProjectID,
		arg.OrganizationID,
		arg.AmaraID,
		arg.Widget2ID,
		arg.PriyaID,
		arg.Widget3ID,
		arg.JonasID,
		arg.Widget4ID,
		arg.MateoID,
		arg.Widget5ID,
		arg.HanaID,
		arg.Widget6ID,
	)
	return err
}

const activitySetClaudeTagChatSlack = `-- name: ActivitySetClaudeTagChatSlack :exec
UPDATE chats SET session_surface = 'claude-tag', slack_team_id = 'T0DEMO0001', slack_channel_id = 'DEMO_CHANNEL', slack_channel_name = 'demo-releases'
WHERE id = $1 AND project_id = $2
`

type ActivitySetClaudeTagChatSlackParams struct {
	ChatID    uuid.UUID
	ProjectID uuid.UUID
}

func (q *Queries) ActivitySetClaudeTagChatSlack(ctx context.Context, arg ActivitySetClaudeTagChatSlackParams) error {
	_, err := q.db.Exec(ctx, activitySetClaudeTagChatSlack, arg.ChatID, arg.ProjectID)
	return err
}
